# ---------------- writer + assertion ----------------
batches = json.load(open(f'{BASE}/runs/round64/batches.json'))
want = batches['B13'] + batches['B14'] + batches['B15']
assert len(want) == 60, len(want)
assert set(CASES.keys()) == set(want), (set(want) ^ set(CASES.keys()))
for cid in want:
    c = CASES[cid]
    dl, rl = S5LINES[cid]
    basis = c['core'] + '\n定式核對——動化方向：' + dl + '。\n定式核對——反轉條件：' + rl + '。\n' + c['timing'] + '\n' + c['gran']
    obj = {'case_id': cid, 'prediction_text': c['prediction_text'], 'basis': basis,
           'confidence': c['confidence'], 'trigger': c['trigger']}
    with open(f'{OUT}/{cid}.json', 'w', encoding='utf-8') as f:
        json.dump(obj, f, ensure_ascii=False, indent=1)
print('written', len(want))
